// In-memory state: watchlist, global thresholds and the audit trail.
// (A real deployment would back this with a database; the interface stays the same.)
const MAX_ACTION_ENTRIES = 500;
const MAX_SECURITY_ENTRIES = 200;

function createStore() {
  const watchlist = new Map(); // coinId -> { id, note, targetPrice, addedBy, addedAt, updatedAt }
  const thresholds = { volatilityAlertPct: 5 };
  // Two bounded buffers: denied/failed events can be generated by anyone (even a Viewer), so they
  // must never be able to push real state-changing actions out of the log.
  const actionLog = [];
  const securityLog = [];
  let auditSeq = 0;

  function audit({ actor, role, action, details = '', outcome = 'success' }) {
    const entry = {
      id: ++auditSeq,
      ts: new Date().toISOString(),
      actor: actor ?? 'anonymous',
      role: role ?? 'none',
      action,
      details,
      outcome,
    };
    const [buffer, max] = outcome === 'success' ? [actionLog, MAX_ACTION_ENTRIES] : [securityLog, MAX_SECURITY_ENTRIES];
    buffer.push(entry);
    if (buffer.length > max) buffer.shift();
    return entry;
  }

  const now = () => new Date().toISOString();

  return {
    audit,
    auditEntries: (limit = 100) => [...actionLog, ...securityLog].sort((a, b) => b.id - a.id).slice(0, limit), // newest first
    thresholds: () => ({ ...thresholds }),
    setVolatilityAlertPct(value) {
      const previous = thresholds.volatilityAlertPct;
      thresholds.volatilityAlertPct = value;
      return previous;
    },
    watchlist: {
      list: () => [...watchlist.values()],
      has: (id) => watchlist.has(id),
      get: (id) => watchlist.get(id),
      add(id, user, extra = {}) {
        const item = { id, note: '', targetPrice: null, ...extra, addedBy: user, addedAt: now(), updatedAt: now() };
        watchlist.set(id, item);
        return item;
      },
      update(id, patch) {
        const item = { ...watchlist.get(id), ...patch, updatedAt: now() };
        watchlist.set(id, item);
        return item;
      },
      remove: (id) => watchlist.delete(id),
    },
  };
}

module.exports = { createStore };
